from taf.internal.aliasing import aliasing_scope
import logging
from .propsim import Propsim

logger = logging.getLogger()


class propsim(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope(name=__name__, lookup_arg='emulator')

    def setup(self, channel_emulator_config, alias=None):
        """
        Setup and connect to a Keysight Propsim ATE interface for channel emulation
        @param channel_emulator_config: The configuration dictionary, keeping the ip and port of the device
        @param alias: The alias to be used through the text to access the device
        @return:
        """
        logger.info("Setting up Propsim with configuration: {}".format(channel_emulator_config))
        configured_emulator = Propsim(channel_emulator_config)
        configured_emulator.connect()
        self.store.add(configured_emulator, alias)
        return configured_emulator

    @lookup_handler.implicit_lookup
    def teardown(self, emulator=None):
        """
        Disconnects from the Keysight Propsim ATE interface.
        @param emulator:
        @return:
        """
        emulator.disconnect()

    @lookup_handler.implicit_lookup
    def send(self, command, emulator=None):
        """
        Gives the possibility to direct call a command on the ATE interface of the Keysight Propsim
        @param command: The ATE command to send to Propsim
        @param emulator: Emulator instance to use (by alias)
        @return: The response of the ATE command

        .. code-block:: robotframework
            *** Settings ***
            Library   taf.hw.propsim   WITH NAME   propsim
            Test Setup       Setup Keysight Propsim
            Test Teardown    Teardown Keysight Propsim

            *** Test Cases ***
            Keysight Propsim Send Command
                ${gain_of_output_2}=  propsim.Send   command=outp:gain:ch? 2   alias=PropsimAlias

            *** Keywords ***
            Setup Keysight Propsim
                ${config}=  Create Dictionary  vendor=Keysight  product=Propsim  propsim_ip=127.0.0.1  propsim_port=3334
                propsim.Setup  channel_emulator_config=${config}   alias=PropsimAlias

            Teardown Keysight Propsim
                propsim.Teardown   PropsimAlias
        """
        return emulator.send_and_check_for_errors(command)

    @lookup_handler.implicit_lookup
    def set_output_gain(self, output_number, gain, emulator=None):
        """
        Sets the output gain for a specific output_number
        .. code-block:: robotframework
            propsim.Set Output Gain   <output_number>  <gain>  <alias>
        """
        return emulator.send_and_check_for_errors("outp:gain:ch {},{}".format(output_number, gain))

    @lookup_handler.implicit_lookup
    def query_output_gain(self, output_number, emulator=None):
        """
        Get for an output_number the output gain
        .. code-block:: robotframework
            ${output_gain}=  propsim.Get Output Gain   <output_number>   <alias>
        """
        return emulator.send_and_check_for_errors("outp:gain:ch? {}".format(int(output_number)))

    @lookup_handler.implicit_lookup
    def query_input_power_level(self, input_number, emulator=None):
        """
        Get the average input level of an input port
        .. code-block:: robotframework
            ${input_power_level}=  propsim.Get Input Power Level   <input_number>   <alias>
        """
        return emulator.send_and_check_for_errors("inp:lev:amp:ch? {}".format(int(input_number)))

    @lookup_handler.implicit_lookup
    def set_input_power_level(self, input_number, dbm_value, emulator=None):
        """
        Set average input level
        .. code-block:: robotframework
             propsim.Set Input Power Level   <input number>   <alias>
        """
        return emulator.send_and_check_for_errors("inp:lev:amp:ch {},{}".format(int(input_number), float(dbm_value)))

    @lookup_handler.implicit_lookup
    def set_output_power_level(self, output_number, amplitude_value, emulator=None):
        """
        Set average output level for output_number with amplitude_value
        .. code-block:: robotframework
             propsim.Set Output Power Level   <output_number>   <alias>
        """
        return emulator.send_and_check_for_errors("outp:lev:amp:ch {},{}".format(int(output_number),
                                                                                 float(amplitude_value)))

    @lookup_handler.implicit_lookup
    def query_output_power_level(self, output_number, emulator=None):
        """
        Get Out power level
        .. code-block:: robotframework
             propsim.Set Output Power Level   <output_number>   <alias>
        """
        return emulator.send_and_check_for_errors("outp:lev:amp:ch? {}".format(int(output_number)))

    @lookup_handler.implicit_lookup
    def query_output_state(self, output_number, emulator=None):
        """
        Get channel output state (enable / disable) from output_number
        .. code-block:: robotframework
            propsim.Get Output State    <output_number>   <alias>
        """
        return emulator.send_and_check_for_errors("outp:en? {}".format(int(output_number)))

    @lookup_handler.implicit_lookup
    def enable_output(self, output_number, emulator=None):
        """
        Enables Output <output_number>
        .. code-block:: robotframework
            propsim.Enable Output    <output_number>   <alias>
        """
        return emulator.send_and_check_for_errors("outp:en {},1".format(output_number))

    @lookup_handler.implicit_lookup
    def disable_output(self, output_number, emulator=None):
        """
        Disables Output <output_number>
        .. code-block:: robotframework
            propsim.Disable Output    <output_number>   <alias>
        """
        return emulator.send_and_check_for_errors("outp:en {},0".format(output_number))

    @lookup_handler.implicit_lookup
    def query_input_state(self, input_number, emulator=None):
        """
        Get the state, if input input_number is enabled or disabled
        .. code-block:: robotframework
            propsim.Get Input State    <input_number>   <alias>
        """
        return emulator.send_and_check_for_errors("inp:en? {}".format(input_number))

    @lookup_handler.implicit_lookup
    def enable_input(self, input_number, emulator=None):
        """
        Enables the input <input_number>
        .. code-block:: robotframework
            propsim.Enable Input    <input_number>   <alias>
        """
        return emulator.send_and_check_for_errors("inp:en {},1".format(input_number))

    @lookup_handler.implicit_lookup
    def disable_input(self, input_number, emulator=None):
        """
        Disables the input <input_number>
        .. code-block:: robotframework
            propsim.Disable Input    <input_number>   <alias>
        """
        return emulator.send_and_check_for_errors("inp:en {},0".format(input_number))

    @lookup_handler.implicit_lookup
    def query_number_of_channel_groups(self, emulator=None):
        """
        Get Number of Channel Groups
        .. code-block:: robotframework
            propsim.Get Number of Channel Groups    <alias>
        """
        return emulator.send_and_check_for_errors("gro:get?")

    @lookup_handler.implicit_lookup
    def query_channels_of_channel_group(self, group_number, emulator=None):
        """
        Get the channel numbers of a channel group.
        .. code-block:: robotframework
            propsim.Get Channels Of Group    <group_number>    <alias>
        """
        return emulator.send_and_check_for_errors("gro:ch:get? {}".format(group_number))

    @lookup_handler.implicit_lookup
    def query_name_of_channel_group(self, group_number, emulator=None):
        """
        Get the name of a channel group given by group_number
        .. code-block:: robotframework
            propsim.Get Name Of Channel Group    <group number>    <alias>
        """
        return emulator.send_and_check_for_errors("gro:name? {}".format(group_number))

    @lookup_handler.implicit_lookup
    def query_outputs_of_channel_group(self, group_number, emulator=None):
        """
        Get outputs of the channel group defined by group_number.
        .. code-block:: robotframework
            propsim.Get Outputs Of Channel Group    <group number>    <alias>
        """
        return emulator.send_and_check_for_errors("gro:out:get? {}".format(group_number))

    @lookup_handler.implicit_lookup
    def query_inputs_of_channel_group(self, group_number, emulator=None):
        """
        Get the inputs of the channel group defined by group_number.
        .. code-block:: robotframework
            propsim.Get Inputs Of Channel Group    <group number>    <alias>
        """
        return emulator.send_and_check_for_errors("gro:in:get? {}".format(group_number))

    @lookup_handler.implicit_lookup
    def load_emulation_file(self, file_path, emulator=None):
        """
        Load the emulation file in Propsim.
        @param file_path: the complete path on the propsim windows host
        @param emulator: Emulator Instance / alias
        @return:
        .. code-block:: robotframework
            propsim.Load Emulation File    D:\\Path To\\Emulationfile.smu    <alias>
        """
        return emulator.send_and_check_for_errors("calc:filt:file {}".format(file_path))

    @lookup_handler.implicit_lookup
    def start_emulation(self, emulator=None):
        """
        Starts the emulation
        @param emulator:
        @return:
        .. code-block:: robotframework
            propsim.Start Emulation    <alias>
        """
        return emulator.send_and_check_for_errors("diag:simu:go")

    @lookup_handler.implicit_lookup
    def stop_emulation(self, emulator=None):
        """
        Stops/pauses the emulation
        @param emulator:
        @return:
        .. code-block:: robotframework
            propsim.Stop Emulation    <alias>
        """
        return emulator.send_and_check_for_errors("diag:simu:stop")

    @lookup_handler.implicit_lookup
    def close_emulation(self, emulator=None):
        """
        Closes the emulation
        @param emulator:
        @return:
        .. code-block:: robotframework
            propsim.Close Emulation    <alias>
        """
        return emulator.send_and_check_for_errors("diag:simu:close")

    @lookup_handler.implicit_lookup
    def reset_emulator(self, emulator=None):
        """
        Resets the channel emulator
        @param emulator:
        @return:
        .. code-block:: robotframework
            propsim.Reset Emulator    <alias>
        """
        return emulator.send_and_check_for_errors("*RST")

    @lookup_handler.implicit_lookup
    def query_emulation_state(self, emulator=None):
        """
        Gets the emulation state
        @param emulator:
        @return:
        .. code-block:: robotframework
            propsim.Get Emulation State    <alias>
        """
        return emulator.send_and_check_for_errors("diag:simu:state?")

    @lookup_handler.implicit_lookup
    def query_system_information(self, emulator=None):
        """
        Gets the system information (in comma separated form)
        @param emulator:
        @return:
        .. code-block:: robotframework
            propsim.Get System Information    <alias>
        """
        return emulator.send_and_check_for_errors("*IDN?")
